import re

def tokenize(text):
    lowered = text.lower()
    words = re.findall(r"[a-z0-9']+", lowered)
    return words

def tokens_and_types(text):
    words = tokenize(text)
    unique_words = []
    for w in words:
        if w not in unique_words:
            unique_words.append(w)
    return (len(words), len(unique_words))

def top_words(text, k):
    words = tokenize(text)
    counts = {}
    for w in words:
        if w in counts:
            counts[w] = counts[w] + 1
        else:
            counts[w] = 1
    items = []
    for w in counts:
        items.append((w, counts[w]))
    # sorting by count descending and word ascending
    items.sort(key=lambda x: (-x[1], x[0]))
    return items[:k]

print(tokens_and_types("Bohat acha match tha, bohat acha!"))

